package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.within;

import org.junit.jupiter.api.Test;

/**
 * Unit spec for row-count coverage across plan kinds.
 * <p>
 * The point of this milestone is not any individual formula but a structural property: a chain is only priceable end to
 * end if every link reports its row count. Before {@code SlotPlan.estimateRows} existed, six plan kinds — filter, inner
 * join, left join, union, minus, extension — reported unknown, so a single OPTIONAL or FILTER anywhere in a join made
 * everything downstream of it unpriceable and dispatch fell back to declaration order.
 * <p>
 * {@link #aChainContainingEachPlanKindIsPriceableEndToEnd()} is the test that states that property directly; the others
 * pin the individual algebra.
 */
public class LmdbNativeCardinalityCoverageTest {

	private static final int ROOT = 0;
	private static final int FIRST = 1;
	private static final int SECOND = 2;

	private static PatternPlan pattern(Term subject, long predicate, Term object, double estimate) {
		return new PatternPlan(subject, Term.constant(predicate), object, Term.unbound(),
				ContextConstraint.UNRESTRICTED, false, estimate);
	}

	private static PatternPlan driver(double rows) {
		return pattern(Term.slot(ROOT), 7L, Term.constant(8L), rows);
	}

	private static PatternPlan probe(int objectSlot, long predicate, double rows) {
		return pattern(Term.slot(ROOT), predicate, Term.slot(objectSlot), rows);
	}

	private static double rows(SlotPlan plan) {
		return LmdbNativeWork.rowsOut(plan, null, 0L);
	}

	@Test
	public void filterIsBoundedAboveByItsArgument() {
		PatternPlan arg = driver(10D);
		double filtered = rows(new FilterPlan(arg, null, -1L));

		assertThat(filtered)
				.as("a filter can only remove rows, never add them")
				.isEqualTo(rows(arg));
	}

	@Test
	public void extensionDoesNotChangeRowCount() {
		PatternPlan arg = driver(10D);

		assertThat(rows(new ExtensionPlan(arg, new CopyBinding[0])))
				.as("an extension binds more slots per row; it does not produce more rows")
				.isEqualTo(rows(arg));
	}

	@Test
	public void unionSumsItsArms() {
		PatternPlan left = driver(10D);
		PatternPlan right = pattern(Term.slot(FIRST), 9L, Term.constant(8L), 20D);

		assertThat(rows(new UnionPlan(left, right)))
				.as("SPARQL UNION does not deduplicate, so both arms' rows survive")
				.isCloseTo(rows(left) + rows(right), within(1e-9));
	}

	@Test
	public void minusIsBoundedAboveByItsLeftArm() {
		PatternPlan left = driver(10D);
		PatternPlan right = probe(FIRST, 9L, 100D);

		assertThat(rows(new MinusPlan(left, right, 0L)))
				.as("MINUS only removes left rows")
				.isEqualTo(rows(left));
	}

	@Test
	public void innerJoinMultipliesByThePerProbeEstimate() {
		PatternPlan left = driver(10D);
		PatternPlan right = probe(FIRST, 9L, 100D);

		double expected = rows(left) * LmdbNativeWork.rowsOut(right, null, left.producedMask());
		assertThat(rows(new JoinPlan(left, right))).isCloseTo(expected, within(1e-6));
	}

	@Test
	public void leftJoinNeverEmitsFewerRowsThanItsLeftArm() {
		PatternPlan left = driver(100D);
		// A right arm that matches almost nothing: an inner join would collapse, a left join must not.
		PatternPlan sparse = probe(FIRST, 9L, 0D);

		double leftRows = rows(left);
		assertThat(rows(new LeftJoinPlan(left, sparse)))
				.as("a left row with no match still emits once, so OPTIONAL can never shrink its left arm")
				.isGreaterThanOrEqualTo(leftRows);
		assertThat(rows(new JoinPlan(left, sparse)))
				.as("the inner join over the same arms may collapse -- that is the difference being modelled")
				.isLessThanOrEqualTo(rows(new LeftJoinPlan(left, sparse)));
	}

	@Test
	public void aChainContainingEachPlanKindIsPriceableEndToEnd() {
		// One of every previously-unpriceable kind, stacked, then joined behind a driver. The expected-work channel
		// must price the composition without promoting sampled row estimates to hard work bounds.
		SlotPlan stacked = new FilterPlan(
				new ExtensionPlan(
						new UnionPlan(probe(FIRST, 9L, 5D), probe(SECOND, 11L, 7D)),
						new CopyBinding[0]),
				null, -1L);

		LmdbNativeWork.Chain chain = LmdbNativeWork.chain(new SlotPlan[] { driver(10D), stacked }, 2, null, 0L);

		assertThat(chain.estimatedPriceable())
				.as("filter over extension over union, chained behind a pattern, must have an expected price")
				.isTrue();
		assertThat(chain.estimatedWork()).isFinite().isGreaterThan(0D);
		assertThat(chain.rows()).isFinite().isGreaterThan(0D);
		assertThat(chain.known()).isFalse();
		assertThat(chain.work().known()).isFalse();
	}

	@Test
	public void nestedMultiJoinRemainsPriceableThroughFilterAndOptional() {
		PatternPlan optionalLeft = driver(10D);
		MultiJoinPlan nested = new MultiJoinPlan(new SlotPlan[] {
				probe(FIRST, 9L, 5D), probe(SECOND, 11L, 7D) }, new MaskedFilter[0]);
		FilterPlan filteredNested = new FilterPlan(nested, null, -1L);
		LeftJoinPlan optional = new LeftJoinPlan(optionalLeft, filteredNested);

		double expected = LmdbNativeWork.expectedWork(optional, null, 0L);
		assertThat(expected)
				.as("expected work must compose nested join, filter and OPTIONAL estimates")
				.isFinite()
				.isGreaterThan(0D);
		assertThat(LmdbNativeWork.rowsOut(optional, null, 0L))
				.as("OPTIONAL preserves every left row even when its nested right side is empty")
				.isGreaterThanOrEqualTo(LmdbNativeWork.rowsOut(optionalLeft, null, 0L));
		assertThat(nested.estimateWork(null, 0L).known())
				.as("nested-loop planning estimates do not become hard work bounds")
				.isFalse();
		assertThat(optional.estimateWork(null, 0L).known())
				.as("OPTIONAL's replay and hash alternatives remain unbounded")
				.isFalse();
	}

	@Test
	public void minusContainingNestedMultiJoinRemainsPriceableInAChain() {
		MultiJoinPlan left = new MultiJoinPlan(new SlotPlan[] {
				probe(FIRST, 9L, 5D), probe(SECOND, 11L, 7D) }, new MaskedFilter[0]);
		MultiJoinPlan right = new MultiJoinPlan(new SlotPlan[] {
				probe(FIRST, 13L, 3D), pattern(Term.slot(ROOT), 15L, Term.slot(3), 2D) }, new MaskedFilter[0]);
		MinusPlan minus = new MinusPlan(left, right, 1L << ROOT);
		LmdbNativeWork.Chain chain = LmdbNativeWork.chain(new SlotPlan[] { driver(12D), minus }, 2, null, 0L);

		assertThat(chain.estimatedPriceable())
				.as("MINUS with nested multi-join arms remains priceable in a larger chain")
				.isTrue();
		assertThat(chain.estimatedWork()).isFinite().isGreaterThan(0D);
		assertThat(LmdbNativeWork.rowsOut(minus, null, 0L))
				.as("MINUS cannot emit more rows or bindings than its left arm")
				.isEqualTo(LmdbNativeWork.rowsOut(left, null, 0L));
		assertThat(minus.producedMask())
				.as("MINUS does not expose variables produced only by its right arm")
				.isEqualTo(left.producedMask());
		assertThat(minus.estimateWork(null, 0L).known())
				.as("right-side replay and verdict reuse do not become a hard work bound")
				.isFalse();
		assertThat(chain.work().known()).isFalse();
	}

	@Test
	public void nestedExpectedQuotesVisitEachChildOnlyLinearly() {
		int shallowDepth = 4;
		int deepDepth = 9;
		assertLinearInvocationGrowth("unary", 1, shallowDepth, deepDepth);
		assertLinearInvocationGrowth("binary", 2, shallowDepth, deepDepth);
		assertLinearInvocationGrowth("mixed", 0, shallowDepth, deepDepth);
		EstimateVisits shallowUnary = estimateUnaryQuoteVisits(shallowDepth);
		int deepUnaryDepth = 16;
		EstimateVisits deepUnary = estimateUnaryQuoteVisits(deepUnaryDepth);
		assertLinearGrowth("unary without wrappers", "hard work quotes", shallowDepth,
				shallowUnary.workQuotes(), deepUnaryDepth, deepUnary.workQuotes());
	}

	@Test
	public void disjointMinusExpectedQuoteChargesOneIndependentRightDrain() {
		CountingPlan left = new CountingPlan(1L, 3D, 5D, new int[1], new int[1]);
		CountingPlan right = new CountingPlan(2L, 4D, 7D, new int[1], new int[1]);
		MinusPlan disjoint = new MinusPlan(left, right, 0L);
		MinusPlan correlated = new MinusPlan(left, right, 1L);

		assertThat(LmdbNativeWork.expectedWork(disjoint, null, 0L))
				.as("an independent RHS is drained at most once, regardless of left cardinality")
				.isEqualTo(12D);
		assertThat(LmdbNativeWork.expectedWork(correlated, null, 0L))
				.as("a correlated RHS is probed once per left row")
				.isEqualTo(26D);
		assertThat(LmdbNativeWork.expectedWork(new MinusPlan(
				new CountingPlan(1L, 0D, 0D, new int[1], new int[1]), right, 0L), null, 0L))
						.as("an empty left input never opens the independent RHS")
						.isEqualTo(0D);
		assertThat(LmdbNativeWork.rowsOut(disjoint, null, 0L))
				.as("quoting the one-time drain does not change MINUS output cardinality")
				.isEqualTo(3D);
		assertThat(disjoint.estimateWork(null, 0L).known())
				.as("the expected-only RHS charge does not turn MINUS alternatives into a hard interval")
				.isFalse();
	}

	private static void assertLinearInvocationGrowth(String shape, int arity, int shallowDepth, int deepDepth) {
		EstimateVisits shallow = estimateInvocationCount(shallowDepth, arity);
		EstimateVisits deep = estimateInvocationCount(deepDepth, arity);
		assertLinearGrowth(shape, "row estimates", shallowDepth, shallow.rowEstimates(), deepDepth,
				deep.rowEstimates());
		assertLinearGrowth(shape, "hard work quotes", shallowDepth, shallow.workQuotes(), deepDepth,
				deep.workQuotes());
	}

	private static void assertLinearGrowth(String shape, String channel, int shallowDepth, int shallowVisits,
			int deepDepth, int deepVisits) {
		assertThat(deepVisits)
				.as("nested %s %s should grow linearly; depth %s visits %s, depth %s visits %s",
						shape, channel, shallowDepth, shallowVisits, deepDepth, deepVisits)
				.isLessThanOrEqualTo(shallowVisits * 4);
	}

	private static EstimateVisits estimateInvocationCount(int depth, int arity) {
		int[] rowEstimateCalls = new int[1];
		int[] hardWorkQuotes = new int[1];
		int nextSlot = 0;
		SlotPlan nested = new CountingPlan(1L << nextSlot++, 1D, 1D, rowEstimateCalls, hardWorkQuotes);
		for (int i = 0; i < depth; i++) {
			SlotPlan wrapped = switch (i % 4) {
			case 0 -> new FilterPlan(nested, null, -1L);
			case 1 -> new LeftJoinPlan(nested,
					new CountingPlan(1L << nextSlot++, 1D, 1D, rowEstimateCalls, hardWorkQuotes));
			case 2 -> new MinusPlan(nested,
					new CountingPlan(1L << nextSlot++, 1D, 1D, rowEstimateCalls, hardWorkQuotes), 0L);
			default -> new UnionPlan(nested,
					new CountingPlan(1L << nextSlot++, 1D, 1D, rowEstimateCalls, hardWorkQuotes));
			};
			boolean includeSibling = arity == 2 || arity == 0 && (i & 1) != 0;
			SlotPlan[] children = includeSibling
					? new SlotPlan[] {
							wrapped, new CountingPlan(1L << nextSlot++, 1D, 1D, rowEstimateCalls, hardWorkQuotes) }
					: new SlotPlan[] { wrapped };
			nested = new MultiJoinPlan(children, new MaskedFilter[0]);
		}
		assertThat(LmdbNativeWork.expectedWork(nested, null, 0L)).isFinite().isGreaterThan(0D);
		assertThat(LmdbNativeWork.rowsOut(nested, null, 0L)).isFinite();
		return new EstimateVisits(rowEstimateCalls[0], hardWorkQuotes[0]);
	}

	private static EstimateVisits estimateUnaryQuoteVisits(int depth) {
		int[] rowEstimateCalls = new int[1];
		int[] hardWorkQuotes = new int[1];
		int nextSlot = 0;
		SlotPlan nested = new CountingPlan(1L << nextSlot++, 1D, 1D, rowEstimateCalls, hardWorkQuotes);
		for (int i = 0; i < depth; i++) {
			UnionPlan withCountedSibling = new UnionPlan(nested,
					new CountingPlan(1L << nextSlot++, 1D, 1D, rowEstimateCalls, hardWorkQuotes));
			nested = new MultiJoinPlan(new SlotPlan[] { withCountedSibling }, new MaskedFilter[0]);
		}
		assertThat(LmdbNativeWork.expectedWork(nested, null, 0L)).isFinite().isGreaterThan(0D);
		assertThat(LmdbNativeWork.rowsOut(nested, null, 0L)).isFinite();
		return new EstimateVisits(rowEstimateCalls[0], hardWorkQuotes[0]);
	}

	private static final class CountingPlan implements SlotPlan {
		private final long producedMask;
		private final double rows;
		private final double work;
		private final int[] rowEstimateCalls;
		private final int[] hardWorkQuotes;

		private CountingPlan(long producedMask, double rows, double work, int[] rowEstimateCalls,
				int[] hardWorkQuotes) {
			this.producedMask = producedMask;
			this.rows = rows;
			this.work = work;
			this.rowEstimateCalls = rowEstimateCalls;
			this.hardWorkQuotes = hardWorkQuotes;
		}

		@Override
		public RowCursor open(RowState row) {
			return new SingletonCursor();
		}

		@Override
		public long producedMask() {
			return producedMask;
		}

		@Override
		public LmdbNativeWork estimateWork(RowState row, long boundMask) {
			hardWorkQuotes[0]++;
			return LmdbNativeWork.exact(work);
		}

		@Override
		public double estimateRows(RowState row, long boundMask) {
			rowEstimateCalls[0]++;
			return rows;
		}
	}

	private record EstimateVisits(int rowEstimates, int workQuotes) {
	}

	@Test
	public void anUnpriceableLeafStillPoisonsOnlyWhatDependsOnIt() {
		SlotPlan unpriceable = new SlotPlan() {
			@Override
			public RowCursor open(RowState row) {
				throw new UnsupportedOperationException();
			}

			@Override
			public long producedMask() {
				return 1L << SECOND;
			}
		};

		assertThat(rows(new UnionPlan(driver(10D), unpriceable)))
				.as("a union is only as priceable as both its arms")
				.isNaN();
		assertThat(rows(new FilterPlan(driver(10D), null, -1L)))
				.as("but a sibling plan that does not contain it is unaffected")
				.isNotNaN();
	}

	@Test
	public void estimateRemainsTheLegacyChannelAndIsUntouched() {
		// The whole reason estimateRows exists as a second channel: SlotPlan.estimate feeds admission decisions that
		// predate the cost model, and its "infinity means unknown" sentinel must keep working.
		assertThat(new FilterPlan(driver(10D), null, -1L).estimate(null))
				.isEqualTo(Double.POSITIVE_INFINITY);
		assertThat(new UnionPlan(driver(10D), driver(5D)).estimate(null))
				.isEqualTo(Double.POSITIVE_INFINITY);
	}
}
